def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def closestValueInBst(tree, target):
    val, left, right = parse(tree)
    best = val[0]
    u = 0
    while u != -1:
        x = val[u]
        if (abs(x - target), x) < (abs(best - target), best):
            best = x
        u = left[u] if target < x else right[u]
    return best
